#include "bits/stdc++.h"using namespace std;#define int long long void print_directory(const deque<string>& directory) {    if (directory.empty()) {        cout << "/\n";        return;    }    for (const string& folder : directory) {        cout << "/" << folder;    }    cout << "/\n";} void change_directory(deque<string>& current_directory, string input) {    if (!input.empty() && input[0] == '/') {        current_directory.clear();    }     stringstream ss(input);    string temp;    while (getline(ss, temp, '/')) {        if (temp == "..") {            if (!current_directory.empty()) {                current_directory.pop_back();            }        } else if (!temp.empty() && temp != ".") {            current_directory.push_back(temp);        }    }} int32_t main() {    int t;    if (!(cin >> t)) return 0;    string dummy;     getline(cin, dummy);     deque<string> directory;    while (t--) {        string line;        getline(cin, line);                if (line == "pwd") {            print_directory(directory);        } else if (line.substr(0, 3) == "cd ") {            string path = line.substr(3);            change_directory(directory, path);        }    }    return 0;}